=== lib/resolve.sh
     1	# resolve.sh — effective value of a setting for a host.
     2	# Most specific scope wins: host.<host>.<s>, then pool.<pool>.<s>, then global.<s>.
     3	
     4	# scope_key SCOPE HOST POOL SETTING
     5	scope_key() {
     6	  case "$1" in
     7	    host)   printf 'host.%s.%s' "$2" "$4" ;;
     8	    pool)   printf 'pool.%s.%s' "$3" "$4" ;;
     9	    global) printf 'global.%s' "$4" ;;
    10	  esac
    11	}
    12	
    13	# resolve HOST POOL SETTING — prints the value; status 1 if no scope has it.
    14	resolve() {
    15	  local host=$1 pool=$2 setting=$3 scope
    16	  for scope in $SCOPES; do
    17	    cfg_get "$(scope_key "$scope" "$host" "$pool" "$setting")" && return 0
    18	  done
    19	  return 1
    20	}
=== lib/render.sh
     1	# render.sh — app.conf for one host from the template.
     2	
     3	# render_host HOST POOL RELEASE — writes the file to stdout.
     4	render_host() {
     5	  local host=$1 pool=$2 release=$3 s val script=""
     6	  for s in $(template_settings); do
     7	    val=$(resolve "$host" "$pool" "$s") || { warn "no value for $s on $host"; return 1; }
     8	    case "$val" in *$'\n'*) warn "multi-line value for $s on $host"; return 1 ;; esac
     9	    script="${script}s|{{$s}}|$(sed_repl_escape "$val")|g;"
    10	  done
    11	  printf '# generated by rollout for %s (pool %s, release %s) — do not edit on the host\n' \
    12	    "$host" "$pool" "$release"
    13	  sed -e "$script" "$TEMPLATE"
    14	}
    15	
    16	# rendered_value FILE SETTING-LINE-KEY — value of "key = value" in a rendered file
    17	rendered_value() {
    18	  awk -v k="$2" '{ i = index($0, " = ") } i && substr($0, 1, i - 1) == k { print substr($0, i + 3); exit }' "$1"
    19	}
=== lib/release.sh
     1	# release.sh — release files: "@release <id>" plus "<key> = <value>" lines.
     2	
     3	release_file() { printf '%s/%s.rel' "$RELEASE_DIR" "$1"; }
     4	
     5	# release_id FILE
     6	release_id() { awk '$1 == "@release" { print $2; exit }' "$1"; }
     7	
     8	# release_changes FILE — key<TAB>value, in file order.
     9	release_changes() {
    10	  local line key val
    11	  while IFS= read -r line || [ -n "$line" ]; do
    12	    case "$line" in ''|'#'*|'@'*) continue ;; esac
    13	    key=$(trim "${line%%=*}")
    14	    val=$(trim "${line#*=}")
    15	    printf '%s\t%s\n' "$key" "$val"
    16	  done < "$1"
    17	}
    18	
    19	# template_settings — setting names used by the template.
    20	template_settings() {
    21	  grep -o '{{[a-z_]*}}' "$TEMPLATE" | tr -d '{}' | sort -u
    22	}
    23	
    24	# release_check FILE — every key must be <scope>.<...>.<setting> with a known
    25	# setting, pool and host.
    26	release_check() {
    27	  local key val setting scope mid bad=0 settings
    28	  settings=" $(template_settings | tr '\n' ' ') "
    29	  while IFS=$'\t' read -r key val; do
    30	    scope=${key%%.*}
    31	    setting=${key##*.}
    32	    mid=${key#*.}; mid=${mid%.*}
    33	    case " $settings " in *" $setting "*) ;; *) warn "unknown setting in $key"; bad=1; continue ;; esac
    34	    case "$scope" in
    35	      global) [ "$mid" = "$setting" ] || { warn "bad global key $key"; bad=1; } ;;
    36	      pool)   known_pool "$mid" || { warn "unknown pool in $key"; bad=1; } ;;
    37	      host)   known_host "$mid" || { warn "unknown host in $key"; bad=1; } ;;
    38	      *)      warn "unknown scope in $key"; bad=1 ;;
    39	    esac
    40	    [ -n "$val" ] || { warn "empty value for $key"; bad=1; }
    41	  done < <(release_changes "$1")
    42	  return "$bad"
    43	}
=== lib/common.sh
     1	# common.sh — logging, configuration loading and small guards shared by
     2	# the wrapper and every step script.
     3	
     4	log()  { printf '[%s] %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; }
     5	warn() { printf '[%s] warn: %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; }
     6	die()  { printf '[%s] error: %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; exit "${2:-1}"; }
     7	
     8	load_conf() {
     9	  local f="$ROLLOUT_HOME/conf/rollout.conf"
    10	  [ -r "$f" ] || die "missing config $f"
    11	  # shellcheck disable=SC1090
    12	  . "$f"
    13	}
    14	
    15	require_file() {
    16	  [ -f "$1" ] || die "${2:-file} not found: $1"
    17	  [ -r "$1" ] || die "${2:-file} not readable: $1"
    18	}
    19	
    20	ensure_dir() {
    21	  mkdir -p "$1" 2>/dev/null || die "cannot create directory $1"
    22	  [ -w "$1" ] || die "directory not writable: $1"
    23	}
    24	
    25	# Per-release working area: $WORK_DIR/<release id>
    26	run_dir() { printf '%s/%s' "$WORK_DIR" "$1"; }
    27	
    28	host_out() { printf '%s/hosts/%s/app.conf' "$OUT_DIR" "$1"; }
=== lib/text.sh
     1	# text.sh — small string helpers.
     2	
     3	# trim STRING — strip leading/trailing blanks
     4	trim() {
     5	  local s=$1
     6	  s=${s#"${s%%[![:space:]]*}"}
     7	  s=${s%"${s##*[![:space:]]}"}
     8	  printf '%s' "$s"
     9	}
    10	
    11	# sed_repl_escape STRING — make STRING safe as the replacement part of
    12	# s|pattern|replacement| (escapes backslash, '&' and the '|' delimiter).
    13	sed_repl_escape() {
    14	  printf '%s' "$1" | sed -e 's/[\\&|]/\\&/g'
    15	}
    16	
    17	# key_file KEY — a file-name-safe form of a config key
    18	key_file() { printf '%s' "$1" | tr -c 'a-zA-Z0-9._-' '_'; }
=== lib/inventory.sh
     1	# inventory.sh — host list and pools.
     2	
     3	# active_hosts — host<TAB>pool for every host that gets a config.
     4	active_hosts() {
     5	  require_file "$HOSTS_FILE" "host list"
     6	  awk -F'|' '!/^#/ && NF >= 4 && $4 != "D" { print $1 "\t" $2 }' "$HOSTS_FILE"
     7	}
     8	
     9	host_pool() {
    10	  awk -F'|' -v h="$1" '!/^#/ && $1 == h { print $2; exit }' "$HOSTS_FILE"
    11	}
    12	
    13	known_host() { [ -n "$(host_pool "$1")" ]; }
    14	
    15	known_pool() {
    16	  awk -F'|' -v p="$1" '!/^#/ && $2 == p { f = 1 } END { exit !f }' "$HOSTS_FILE"
    17	}
=== lib/audit.sh
     1	# audit.sh — rollout history: one line per finished rollout.
     2	# release|mark|hosts|changes
     3	
     4	history_file() { printf '%s/history.log' "$OUT_DIR"; }
     5	
     6	history_add() {
     7	  ensure_dir "$OUT_DIR"
     8	  printf '%s|%s|%s|%s\n' "$1" "$2" "$3" "$4" >> "$(history_file)"
     9	}
    10	
    11	history_show() {
    12	  local f
    13	  f=$(history_file)
    14	  [ -f "$f" ] || return 0
    15	  awk -F'|' '{ printf "%-14s %-9s %3s hosts %3s changes\n", $1, $2, $3, $4 }' "$f"
    16	}
